#!/usr/bin/env bash
#
# nexum-bridge-hash-capture.sh
# =============================================================================
# OPTION A (+ small B hardening) for the stuck-bridge problem.
#
# A - PERSIST THE BURN HASH THE INSTANT IT EXISTS (root fix, no chain scanning):
#   executeContractCall now takes an onHash callback, fired the moment the burn
#   tx hash is discovered in its poll loop - BEFORE the function returns. The
#   bridge flow uses it to write /bridge/:id/burned immediately, so if the
#   browser dies right after the burn, the hash is already saved and the
#   transfer can always be completed. The existing awaited /burned write stays
#   as the authoritative idempotent (COALESCE) write. This removes almost all
#   stuck-bridge cases without touching the rate-limited RPC.
#
# B (hardening) - the burn-scanner (backstop) now pauses briefly between block
#   chunks (BURN_SCAN_CHUNK_DELAY_MS, default 250ms) so it is gentler on the
#   RPC. The scanner already honors ARC_RPC_URL / per-chain *_RPC_URL env vars;
#   point those at a dedicated RPC (Alchemy/dRPC/QuickNode free tier) to make
#   log scanning reliable. That is an ENV change, no code needed.
#
# WHAT THIS DELIVERS:
#   nexum-web/hooks/useCircleTx.ts  (EDIT) - onHash param on executeContractCall
#   nexum-web/hooks/useBridge.ts    (EDIT) - persists hash via onHash instantly
#   nexum-api/src/services/bridge/burnScanner.ts (EDIT) - inter-chunk delay
#
# NO contract redeploy. Depends on the burn-scanner already applied
# (nexum-bridge-burn-scanner.sh + the chunked fix) for the scanner file.
#
# DELIVERY: per-file base64 heredoc; decode+verify; backup; idempotent; --revert.
# VERIFY AFTER:
#   cd nexum-web && rm -rf .next && npx tsc --noEmit && npm run build
#   cd nexum-api && npx tsc --noEmit
# =============================================================================
set -euo pipefail
find_root() { local d="$PWD"; while [ "$d" != "/" ]; do [ -d "$d/nexum-web/hooks" ] && [ -d "$d/nexum-api/src" ] && { echo "$d"; return; }; d="$(dirname "$d")"; done; [ -d "$HOME/AfriFX/Nexum-main/nexum-web/hooks" ] && { echo "$HOME/AfriFX/Nexum-main"; return; }; [ -d "$HOME/AfriFX/nexum-web/hooks" ] && { echo "$HOME/AfriFX"; return; }; return 1; }
ROOT="$(find_root)" || { echo "ERROR: repo root not found (needs nexum-web + nexum-api)."; exit 1; }
echo "Repo root: $ROOT"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="$ROOT/.nexum-hash-capture-backups"
CT_PATH="$ROOT/nexum-web/hooks/useCircleTx.ts";                     CT_SHA="7a1c082a1e958b3c47acbe88c8091982a41c2d6cfac14f873ce982a271ee815f"; CT_B64=""
UB_PATH="$ROOT/nexum-web/hooks/useBridge.ts";                       UB_SHA="78a9798db164a615bcee67281f13c1446bf662750324ac0126fcf1757f23d2c5"; UB_B64=""
SC_PATH="$ROOT/nexum-api/src/services/bridge/burnScanner.ts";       SC_SHA="620793612329a752212f65fac3b75c07b00f4cc5b52cc308fdeecd3c6a1ff9e8"; SC_B64=""
restore_edit() { local base="$1" dest="$2" p; p="$(ls -1tr "$BACKUP_DIR"/"$base".* 2>/dev/null | head -n1 || true)"; if [ -n "${p:-}" ] && [ -f "$p" ]; then cp -f "$p" "$dest" && echo "restored $base"; else echo "no backup for $base"; fi; }
revert() { echo "== REVERT =="; restore_edit "useCircleTx.ts" "$CT_PATH"; restore_edit "useBridge.ts" "$UB_PATH"; restore_edit "burnScanner.ts" "$SC_PATH"; rm -f "$BACKUP_DIR"/*.* 2>/dev/null || true; rmdir "$BACKUP_DIR" 2>/dev/null || true; echo "revert complete."; }
if [ "${1:-}" = "--revert" ]; then revert; exit 0; fi
[ -f "$SC_PATH" ] || { echo "ERROR: burnScanner.ts missing - apply the burn-scanner scripts first."; exit 1; }
mkdir -p "$BACKUP_DIR"
write_edit() { local name="$1" path="$2" sha="$3" b64="$4"; local tmp; tmp="$(mktemp)"; printf '%s' "$b64" | base64 -d > "$tmp" || { echo "decode fail $name"; rm -f "$tmp"; exit 1; }; local got; got="$(sha256sum "$tmp" | cut -d' ' -f1)"; [ "$got" = "$sha" ] || { echo "ERROR checksum $name"; echo " expected $sha"; echo " got      $got"; rm -f "$tmp"; exit 1; }; echo "  verified $name"; [ -f "$path" ] && [ ! -f "$BACKUP_DIR/$(basename "$path").$STAMP" ] && cp -f "$path" "$BACKUP_DIR/$(basename "$path").$STAMP" && echo "  backed up $name"; mv -f "$tmp" "$path"; echo "  wrote $path"; }
echo "== APPLY bridge hash-capture (A) + scanner delay (B) =="
write_edit "useCircleTx.ts"  "$CT_PATH" "$CT_SHA" "$CT_B64"
write_edit "useBridge.ts"    "$UB_PATH" "$UB_SHA" "$UB_B64"
write_edit "burnScanner.ts"  "$SC_PATH" "$SC_SHA" "$SC_B64"
echo; echo "== DONE =="
echo "Then, for B, set a dedicated RPC in nexum-api env (Render):"
echo "  ARC_RPC_URL=<your dedicated Arc RPC>   (and BASE_RPC_URL etc. for other sources)"
echo "Verify: cd $ROOT/nexum-web && rm -rf .next && npx tsc --noEmit && npm run build"
echo "        cd $ROOT/nexum-api && npx tsc --noEmit"
echo "Revert: bash $(basename "$0") --revert"
